// Extrai oportunidades e monta comunicado executivo formatado
const data = $input.first().json;
const editais = data.oportunidades_alta_aderencia || [];
const total = editais.length;
const frontendUrl = $env.FRONTEND_URL || 'https://buscador-de-editais-orpin.vercel.app';
const linkPreFiltrado = `${frontendUrl}/?aderencia=Alta`;

// 1. Mensagem em Markdown (Teams / Slack / Discord)
let md = `### 🚨 **Novas Oportunidades de Alta Aderência Encontradas!**\n\n`;
md += `Foram identificados **${total}** edital(is) com alta relevância estratégica para a inovação.\n\n`;

editais.forEach((item, index) => {
  md += `**${index + 1}. ${item.titulo}**\n`;
  md += `🏛️ **Instituição:** ${item.instituicao || 'Não informada'} | 📂 **Tema:** ${item.tematica || 'Geral'}\n`;
  md += `⏳ **Prazo de Submissão:** ${item.prazo || 'Não informado'}\n`;
  md += `📝 **Resumo:** ${item.resumo || 'Sem resumo cadastrado.'}\n`;
  md += `🔗 [Acessar Link Oficial da Chamada](${item.link})\n\n`;
});

md += `---\n`;
md += `👉 **[Visualizar todas as oportunidades no Painel Interativo](${linkPreFiltrado})**`;

// 2. Mensagem em HTML (E-mail)
let html = `
<div style="font-family: Arial, sans-serif; color: #1e293b; max-width: 650px; margin: 0 auto;">
  <div style="background-color: #0284c7; padding: 20px; border-radius: 8px 8px 0 0; text-align: center;">
    <h2 style="color: #ffffff; margin: 0;">🔍 Buscador de Oportunidades para Inovação</h2>
    <p style="color: #e0f2fe; margin: 6px 0 0 0;">Radar Semanal de Editais e Chamadas Públicas</p>
  </div>
  <div style="padding: 24px; border: 1px solid #e2e8f0; border-top: none; border-radius: 0 0 8px 8px; background-color: #ffffff;">
    <p style="font-size: 15px;">Olá equipe,</p>
    <p style="font-size: 15px;">A rodada semanal de varredura identificou <strong>${total} oportunidade(s) com Alta Aderência</strong> aos temas estratégicos cadastrados:</p>
    <hr style="border: none; border-top: 1px solid #e2e8f0; margin: 20px 0;" />
`;

editais.forEach((item, index) => {
  html += `
    <div style="margin-bottom: 22px; padding: 16px; background-color: #f8fafc; border-left: 4px solid #0284c7; border-radius: 4px;">
      <h3 style="margin: 0 0 8px 0; color: #0f172a; font-size: 16px;">${index + 1}. ${item.titulo}</h3>
      <p style="margin: 4px 0; font-size: 13px; color: #475569;"><strong>Instituição:</strong> ${item.instituicao} | <strong>Prazo:</strong> ${item.prazo}</p>
      <p style="margin: 8px 0; font-size: 14px; color: #334155; line-height: 1.4;">${item.resumo}</p>
      <a href="${item.link}" target="_blank" style="color: #0284c7; text-decoration: none; font-size: 13px; font-weight: bold;">↗ Ver edital no site oficial</a>
    </div>
  `;
});

html += `
    <div style="text-align: center; margin-top: 30px;">
      <a href="${linkPreFiltrado}" target="_blank" style="background-color: #0284c7; color: #ffffff; padding: 12px 24px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;">Abrir Painel com Filtro de Alta Aderência</a>
    </div>
  </div>
</div>
`;

return [{
  json: {
    total_alta_aderencia: total,
    link_prefiltrado: linkPreFiltrado,
    mensagem_markdown: md,
    mensagem_html: html,
    editais: editais
  }
}];

const data = $input.first().json;
console.log('Rodada concluída sem novas oportunidades de Alta Aderência nesta execução.');
return [{
  json: {
    status: 'nenhuma_alta_aderencia',
    data_execucao: data.data_execucao,
    total_salvos_ia: data.total_salvos_ia || 0,
    mensagem: 'Varredura semanal concluída. Nenhuma oportunidade inédita de Alta Aderência encontrada nesta rodada.'
  }
}];
